  const token = asRecord(approval?.token) ?? asRecord(resultRecord.token);
  if (!token) return null;

  return op("lifi.approval", rawLabel, [
    chainFactFromRecord(resultRecord) ?? chainFactFromRecord(token),
    tokenFact(token.symbol),
