import { asRecord, asInteger, asString, statusFact } from "../normalize";
import type { ToolFact, ToolMatcher, ToolOperation } from "../types";

/**
 * The orchestrator's `task` tool — one delegation to a child agent.
 *
 * The trace normally renders these through `WorkingAgent`, which owns its own
 * header. This family is the fallback interpretation: it is what a `task`
 * transcript part looks like anywhere `interpretToolStep` is applied to it —
 * a run whose result carries no `agent_id` join key, an older transcript, or a
 * "Phase 0" reload with no live sidecar.
 *
 * Args are the `ChildTaskRequest` (`{label, app, prompt}`); the public result
 * projection is `{agent_id, status, staged_count}`.
 */

const TASK_TOOL_NAME = "task";

/** Enough of the agent id to tell two children apart, without the noise. */
export const shortAgentId = (agentId: string): string => {
  const tail = agentId.slice(-8);
  return tail.length > 0 ? tail : agentId;
};

const looksLikeTaskResult = (
  record: Record<string, unknown> | null,
): boolean => {
  if (!record) return false;
  return typeof record.agent_id === "string" && "status" in record;
};

export const matchTaskDelegation: ToolMatcher = ({
  rawLabel,
  parsedArgs,
  resultRecord,
}) => {
  const isTaskCall =
    rawLabel.trim().toLowerCase() === TASK_TOOL_NAME ||
    looksLikeTaskResult(resultRecord);
  if (!isTaskCall) return null;

  const args = asRecord(parsedArgs);
  const label = asString(args?.label);
  const agentId = asString(resultRecord?.agent_id);
  const status = asString(resultRecord?.status);
  const stagedCount = asInteger(resultRecord?.staged_count) ?? 0;

  const facts: Array<ToolFact | null> = [
    agentId
      ? { kind: "code", value: shortAgentId(agentId), source: "result" }
      : null,
    stagedCount > 0
      ? {
          kind: "count",
          role: "staged",
          value: String(stagedCount),
          source: "result",
        }
      : null,
    // A completed delegation is the quiet default — only say so when it isn't.
    status && status !== "completed" ? statusFact(status) : null,
  ];

  return {
    id: "task.delegate",
    facts: facts.filter((fact): fact is ToolFact => fact != null),
    confidence: "high",
    rawLabel,
    title: label ? `Delegated: ${label}` : "Delegated task",
    failed: status != null && status !== "completed",
  } satisfies ToolOperation;
};

import { humanize } from "../normalize";
import type { InterpretedToolStep, ToolFact, ToolOperation } from "../types";
import { chipForFact, uniqueChips } from "./chips";
import { descriptorFor, iconForDescriptor } from "./descriptors";

const pickFacts = (
  facts: ToolFact[],
  slots: ReturnType<typeof descriptorFor>["chipPlan"],
): ToolFact[] => {
  const picked: ToolFact[] = [];
  const used = new Set<ToolFact>();

  for (const slot of slots) {
    const matches = facts.filter(
      (fact) =>
        fact.kind === slot.kind &&
        (slot.role == null || fact.role === slot.role) &&
        !used.has(fact),
    );
    const selected = slot.repeat ? matches : matches.slice(0, 1);
    selected.forEach((fact) => {
      picked.push(fact);
      used.add(fact);
    });
  }

  return picked;
};

const statusLast = (facts: ToolFact[]): ToolFact[] => [
  ...facts.filter((fact) => fact.kind !== "status"),
  ...facts.filter((fact) => fact.kind === "status"),
];

/** A failure/error status fact — the same signal that renders the "Failed" chip. */
const isFailedStatus = (fact: ToolFact): boolean =>
  fact.kind === "status" && (fact.value === "failed" || fact.value === "error");

export const presentOperation = (
  operation: ToolOperation,
): InterpretedToolStep => {
  const descriptor = descriptorFor(operation);
  const title =
    operation.title ??
    (descriptor.title === "fixed"
      ? (descriptor.fixedTitle ?? humanize(operation.rawLabel))
      : humanize(operation.rawLabel));
  const chips = uniqueChips(
    statusLast(pickFacts(operation.facts, descriptor.chipPlan))
      .map(chipForFact)
      .filter((chip): chip is NonNullable<typeof chip> => chip != null),
  );

  return {
    icon: iconForDescriptor(descriptor, operation),
    title,
    chips,
    confidence: operation.confidence,
    rawLabel: operation.rawLabel,
    failed: operation.failed ?? operation.facts.some(isFailedStatus),
  };
};

import {
  ArrowDownLeftIcon,
  ArrowUpRightIcon,
  BanIcon,
  BlocksIcon,
  CircleCheckIcon,
  CircleXIcon,
  ClockIcon,
  CoinsIcon,
  FuelIcon,
  HashIcon,
  PuzzleIcon,
  ReceiptTextIcon,
  UserIcon,
} from "lucide-react";

import { getChainIcon } from "@/components/icons/chain-map";
import { SolanaIcon } from "@/components/icons/chains";
import {
  SHAPE_ICONS,
  STAGED_ACTION_ICON_REGISTRY,
} from "@/components/assistant-ui/tool-registry";

import { humanize } from "../normalize";
import type { ToolChip, ToolFact } from "../types";

const formatInteger = (value: string): string => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed.toLocaleString("en-US") : value;
};

const shortenAddress = (address: string): string =>
  /^0x[a-fA-F0-9]{40}$/.test(address)
    ? `${address.slice(0, 6)}...${address.slice(-4)}`
    : address;

const formatNativeAmount = (value: string): string => {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return value;
  if (numeric === 0) return "0";

  const formatted = numeric.toLocaleString("en-US", {
    maximumFractionDigits: 5,
    useGrouping: false,
  });

  return formatted === "0" ? "<0.00001" : formatted;
};

const statusChip = (value: string): ToolChip => {
  switch (value) {
    case "queued":
      return { label: "Queued", icon: ClockIcon };
    case "pending":
      return { label: "Pending approval", icon: ClockIcon };
    case "success":
      return { label: "Success", icon: CircleCheckIcon };
    case "failed":
    case "error":
      return { label: "Failed", icon: CircleXIcon };
    case "revoked":
      return { label: "Revoked", icon: BanIcon };
    default:
      return { label: humanize(value) };
  }
};

const stagedActionIcon = (value: string) => {
  const lower = value.toLowerCase().replace(/[_-]+/g, " ");
  for (const [pattern, icon] of STAGED_ACTION_ICON_REGISTRY) {
    if (pattern.test(lower)) return icon;
  }
  return SHAPE_ICONS.staged;
};

export const chipForFact = (fact: ToolFact): ToolChip | null => {
  switch (fact.kind) {
    case "action":
      return {
        label: fact.label ?? humanize(fact.value),
        icon: stagedActionIcon(fact.value),
      };
    case "address":
      if (fact.role === "owner") {
        return { label: shortenAddress(fact.value), icon: UserIcon };
      }
      if (fact.role === "from") {
        return { label: shortenAddress(fact.value), icon: ArrowUpRightIcon };
      }
      if (
        fact.role === "recipient" ||
        fact.role === "spender" ||
        fact.role === "to"
      ) {
        return { label: shortenAddress(fact.value), icon: ArrowDownLeftIcon };
      }
      return { label: shortenAddress(fact.value) };
    case "amount":
      if (fact.role === "native") {
        return {
          label: formatNativeAmount(fact.value),
          icon: getChainIcon(1),
        };
      }
      if (fact.role === "primary" || fact.role === "secondary") {
        return { label: fact.label ?? fact.value, icon: CoinsIcon };
      }
      return { label: fact.label ?? fact.value };
    case "block":
      return { label: formatInteger(fact.value), icon: BlocksIcon };
    case "chain": {
      const chainId = Number(fact.value);
      return {
        label: fact.label ?? fact.value,
        icon: Number.isFinite(chainId) ? getChainIcon(chainId) : undefined,
      };
    }
    case "cluster":
      return { label: fact.label ?? humanize(fact.value), icon: SolanaIcon };
    case "code":
      return { label: fact.label ?? fact.value };
    case "count":
      if (fact.role === "tx") {
        const count = Number(fact.value);
        return {
          label: `${fact.value} tx${count === 1 ? "" : "s"}`,
          icon: ReceiptTextIcon,
        };
      }
      if (fact.role === "results") {
        return { label: `${fact.value} results` };
      }
      if (fact.role === "staged") {
        return { label: `staged ${fact.value}`, icon: SHAPE_ICONS.staged };
      }
      return { label: fact.value };
    case "decoded":
      if (fact.role === "decimals") {
        return {
          label: fact.label ?? `${fact.value} decimals`,
          icon: HashIcon,
        };
      }
      return { label: fact.label ?? fact.value };
    case "gas":
      return { label: `${formatInteger(fact.value)} gas`, icon: FuelIcon };
    case "selector":
      return { label: fact.label ?? fact.value };
    case "skill":
      return { label: fact.label ?? humanize(fact.value), icon: PuzzleIcon };
    case "sourceHost":
      return { label: fact.label ?? fact.value };
    case "status":
      return statusChip(fact.value);
    case "slot":
      return {
        label: fact.label ?? formatInteger(fact.value),
        icon: BlocksIcon,
      };
    case "token":
      return { label: fact.label ?? fact.value, icon: CoinsIcon };
    case "txId":
      return { label: fact.value, icon: ReceiptTextIcon };
    default:
      return null;
  }
};

export const uniqueChips = (chips: ToolChip[]): ToolChip[] => {
  const seen = new Set<string>();
  return chips.filter((chip) => {
    const key = chip.label.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

